// Visual palettes only. Menu names and prices remain in menu.js.
// Keys match the IDs generated by data/flavours.js.

function palette(name, accent, icing, piping, drip, message) {
  return {
    name,
    accent,
    appearance: {
      icingColour: icing,
      pipingColour: piping,
      dripColour: drip,
      messageColour: message,
      cherryColour: '#8f1223',
      candleColour: piping,
      pearlColour: piping,
      sprinkleColour: accent
    }
  };
}

