const fallbackPalette = palette(
  'The signature palette',
  '#a86d5d',
  '#f1e2c8',
  '#fff4df',
  '#895946',
  '#fff1ce'
);

export function getFlavourPalette(id) {
  const source = Object.hasOwn(flavourPalettes, id)
    ? flavourPalettes[id]
    : fallbackPalette;

  // Return fresh objects so edits cannot change the preset.
  return {
    ...source,
    appearance: { ...source.appearance }
  };
}